async function dgAuthEnsure(force=false){
 const s=dgAuthSession();if(!s)return null;const exp=(+s.expires_at||0)*1000;if(!force&&exp>Date.now()+90_000)return s;if(dgAuthRefreshPromise)return dgAuthRefreshPromise;
 dgAuthRefreshPromise=(async()=>{try{const r=await fetch(`${DG_SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:DG_SUPABASE_PUBLISHABLE,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})}),j=await r.json().catch(()=>({}));if(!r.ok||!j.access_token)throw new Error(j.error_description||j.message||'refresh_failed');const next={...j,accountUsername:s.accountUsername,displayName:s.displayName};localStorage.setItem(DG_AUTH_SESSION_KEY,JSON.stringify(next));return next}catch(e){dgRecordError?.('auth-refresh',e);return s}finally{dgAuthRefreshPromise=null}})();return dgAuthRefreshPromise
}
async function dgAuthHeaders(){const s=await dgAuthEnsure();if(!s?.access_token)throw new Error('account_required');return{apikey:DG_SUPABASE_PUBLISHABLE,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'}}
async function dgAccountRequest(body){const c=new AbortController(),t=setTimeout(()=>c.abort(),30000);try{const r=await fetch(DG_ACCOUNT_URL,{method:'POST',headers:{apikey:DG_SUPABASE_PUBLISHABLE,'Content-Type':'application/json'},body:JSON.stringify(body),signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok){const e=new Error(j.error||('account '+r.status));e.data=j;e.status=r.status;throw e}return j}finally{clearTimeout(t)}}
function dgStoreSession(session,meta={}){const next={...session,accountUsername:meta.username||session?.user?.user_metadata?.username||'',displayName:meta.displayName||session?.user?.user_metadata?.full_name||''};localStorage.setItem(DG_AUTH_SESSION_KEY,JSON.stringify(next));localStorage.setItem(DG_ACTIVE_SCOPE_KEY,'user:'+next.user.id);return next}
async function dgRemoveCurrentPushRegistration(){if(!dgIsAccount())return;try{const reg=await navigator.serviceWorker?.ready,sub=await reg?.pushManager?.getSubscription(),headers=await dgAuthHeaders();await fetch(DG_USER_PUSH_URL,{method:'POST',headers,body:JSON.stringify({action:'remove',endpoint:sub?.endpoint||''})})}catch{}}
async function dgLogout(){if(!dgIsAccount())return;dgWriteScopedState(S);await dgRemoveCurrentPushRegistration();try{const s=dgAuthSession();await fetch(`${DG_SUPABASE_URL}/auth/v1/logout`,{method:'POST',headers:{apikey:DG_SUPABASE_PUBLISHABLE,Authorization:`Bearer ${s.access_token}`}})}catch{}localStorage.removeItem(DG_AUTH_SESSION_KEY);localStorage.setItem(DG_ACTIVE_SCOPE_KEY,'guest');const g=dgGuestState()||dgFreshUserState('');localStorage.setItem(STORE,JSON.stringify(g));toast('יצאת מהחשבון · חוזר למצב אורח');setTimeout(()=>location.reload(),450)}

function dgCloudToken(){if(dgIsAccount())return dgAccountRecovery();let k=localStorage.getItem('dvirGymGuestRecoveryLocalV8');if(!k){k=dgMakeRecoveryKey();localStorage.setItem('dvirGymGuestRecoveryLocalV8',k)}return k}
function dgCloudMeta(){try{return JSON.parse(localStorage.getItem(dgScopeMetaKey()))||{}}catch{return{}}}
function dgSetCloudMeta(p){const m={...dgCloudMeta(),...p};localStorage.setItem(dgScopeMetaKey(),JSON.stringify(m));return m}
function dgCloudPaused(){return localStorage.getItem(dgScopeDisabledKey())==='1'}
function dgSetCloudPaused(v){localStorage.setItem(dgScopeDisabledKey(),v?'1':'0');dgCloudStatus=v?'paused':'connecting';try{dgRefreshCloudBadges()}catch{}}
async function dgCloudRequest(action,state=null,baseVersion=null){if(!dgIsAccount())throw Object.assign(new Error('guest_local_only'),{status:401});const headers=await dgAuthHeaders(),body={action,state};if(baseVersion!=null)body.baseVersion=baseVersion;const r=await fetch(DG_USER_MEMORY_URL,{method:'POST',headers,body:JSON.stringify(body)}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok){const e=new Error(j.error||('cloud '+r.status));e.status=r.status;e.data=j;throw e}return j}
dgCloudPush=async function(){if(!dgIsAccount()||!dgAccountRecovery()||dgCloudPaused()||dgCloudBusy||!navigator.onLine)return false;dgCloudBusy=true;try{const meta=dgCloudMeta(),encrypted=await dgEncryptCloudState(dgCloudSnapshot());let j;try{j=await dgCloudRequest('push',encrypted,+meta.cloudVersion||0)}catch(e){if(e.status===409&&e.data?.state){const cloud=await dgDecryptCloudState(e.data.state),merged=dgMergeStates(S,cloud);S=dgNormalizeState(merged,dgCurrentDisplayName());dgWriteScopedState(S);dgSetCloudMeta({cloudVersion:+e.data.version||0,lastCloudAt:e.data.updatedAt?new Date(e.data.updatedAt).getTime():Date.now(),lastConflictAt:Date.now(),lastError:'',encrypted:true});dgCloudBusy=false;renderCurrent();toast('☁ זוהה עדכון נוסף בחשבון · הנתונים מוזגו');return dgCloudPush()}throw e}const now=Date.now(),cloudTs=j.updatedAt?new Date(j.updatedAt).getTime():now;dgSetCloudMeta({lastPushAt:cloudTs,lastCloudAt:cloudTs,cloudVersion:+j.version||1,lastError:'',encrypted:true});dgCloudStatus='live';return true}catch(e){dgRecordError?.('user-cloud-push',e);dgSetCloudMeta({lastError:String(e),lastErrorAt:Date.now()});dgCloudStatus='offline';return false}finally{dgCloudBusy=false;try{dgRefreshCloudBadges()}catch{}}};
dgCloudBoot=async function(){if(!dgIsAccount()){dgCloudStatus='local';try{dgRefreshCloudBadges()}catch{}return false}if(!dgAccountRecovery()){dgCloudStatus='locked';try{dgRefreshCloudBadges()}catch{}return false}if(dgCloudPaused()||!navigator.onLine)return false;dgCloudBusy=true;try{const j=await dgCloudRequest('pull'),meta=dgCloudMeta();if(j.state){let cloud;try{cloud=await dgDecryptCloudState(j.state)}catch{throw new Error('recovery_key_mismatch')}const localChanged=+meta.localModifiedAt||0,lastPush=+meta.lastPushAt||0;if(localChanged>lastPush&&dgMeaningfulState(S)){S=dgNormalizeState(dgMergeStates(S,cloud),dgCurrentDisplayName());dgWriteScopedState(S);dgSetCloudMeta({cloudVersion:+j.version||0,lastCloudAt:j.updatedAt?new Date(j.updatedAt).getTime():Date.now()});dgCloudBusy=false;await dgCloudPush();renderCurrent();return true}S=dgNormalizeState(cloud,dgCurrentDisplayName());dgWriteScopedState(S);const ts=j.updatedAt?new Date(j.updatedAt).getTime():Date.now();dgSetCloudMeta({cloudVersion:+j.version||0,lastPushAt:ts,lastCloudAt:ts,lastError:'',encrypted:true});dgCloudStatus='live';renderCurrent();toast('☁ החשבון האישי סונכרן מהענן');return true}dgCloudBusy=false;return dgCloudPush()}catch(e){dgCloudStatus=String(e).includes('recovery_key_mismatch')?'locked':'offline';dgSetCloudMeta({lastError:String(e),lastErrorAt:Date.now()});if(String(e).includes('recovery_key_mismatch'))toast('Recovery Key לא מתאים לזיכרון המוצפן של החשבון');return false}finally{dgCloudBusy=false;try{dgRefreshCloudBadges()}catch{}}};
function dgCloudStatusText(){if(!dgIsAccount())return'Guest · נשמר רק במכשיר';if(!dgAccountRecovery())return'Cloud נעול · הזן Recovery Key';const m=dgCloudMeta();if(dgCloudStatus==='live')return`Cloud אישי פעיל${m.lastPushAt?' · '+new Date(m.lastPushAt).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'}):''}`;if(!navigator.onLine)return'Offline · יסתנכרן כשתחזור לרשת';return'Cloud אישי מתחבר…'}
async function dgCopyRecovery(){const k=dgAccountRecovery();if(!k){dgOpenAccount('unlock');return}try{await navigator.clipboard.writeText(k);toast('Recovery Key הועתק · שמור אותו במקום פרטי')}catch{toast('לא הצלחתי להעתיק')}}
function dgImportRecovery(){if(!dgIsAccount()){dgOpenAccount('login');return}dgOpenAccount('unlock')}

// Per-user Zero-Cost AI. Guests remain on the local Memory Engine.
const dgStartFreeOAuthV8Base=dgStartFreeOAuth;dgStartFreeOAuth=function(){if(!dgIsAccount()){toast('כדי לחבר Cloud AI צריך חשבון אישי');dgOpenAccount('login');return}return dgStartFreeOAuthV8Base()};
dgKeyVault=async function(action='status',apiKey='',extra={}){if(!dgIsAccount())throw new Error('account_required');const c=new AbortController(),t=setTimeout(()=>c.abort(),25000);try{const headers=await dgAuthHeaders(),r=await fetch(DG_USER_AI_URL,{method:'POST',headers,body:JSON.stringify({action,apiKey,...extra}),signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok){const e=new Error(j.error||('HTTP '+r.status));e.data=j;throw e}dgAiProvider=j.provider||'openrouter';return j}finally{clearTimeout(t)}};
dgCheckAIConfigured=async function(force=false){if(!dgIsAccount()){dgAiConfigured=false;return false}const cache='dvirGymAiConfiguredV8::'+dgCurrentUserId();if(!force&&Date.now()-dgAiStatusCheckedAt<30000)return dgAiConfigured;dgAiStatusCheckedAt=Date.now();try{const j=await dgKeyVault('status');dgAiConfigured=!!j.configured;localStorage.setItem(cache,dgAiConfigured?'1':'0');return dgAiConfigured}catch{dgAiConfigured=localStorage.getItem(cache)==='1';return dgAiConfigured}};
callAI=async function(message,imageData=null){if(!dgIsAccount())throw new Error('account_required');const configured=await dgCheckAIConfigured();if(!configured)throw new Error('free_ai_not_configured');const c=new AbortController(),timer=setTimeout(()=>c.abort(),50000);try{const headers=await dgAuthHeaders(),r=await fetch(DG_USER_COACH_URL,{method:'POST',headers,body:JSON.stringify({message,imageData,history:S.chat.slice(-14),memory:coachMemory()}),signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(j.error||('Zero-Cost AI '+r.status));e.data=j;e.status=r.status;throw e}return j}finally{clearTimeout(timer)}};
const dgFinishFreeOAuthBaseV8=dgFinishFreeOAuth;dgFinishFreeOAuth=async function(){const p=new URLSearchParams(location.search),code=p.get('code');if(!code)return false;if(!dgIsAccount()){history.replaceState({},'',location.pathname);toast('התחבר לחשבון לפני חיבור Cloud AI');return false}let data=null;try{data=JSON.parse(sessionStorage.getItem(DG_OR_PKCE)||localStorage.getItem(DG_OR_PKCE)||'null')}catch{}history.replaceState({},'',location.pathname+(location.hash||''));if(!data?.verifier||Date.now()-(+data.at||0)>15*60e3){toast('חיבור OpenRouter פג תוקף. נסה שוב.');return false}try{toast('מחבר AI חינמי לחשבון שלך…');const j=await dgKeyVault('oauth-exchange','',{code,codeVerifier:data.verifier});sessionStorage.removeItem(DG_OR_PKCE);localStorage.removeItem(DG_OR_PKCE);dgAiConfigured=true;localStorage.setItem('dvirGymAiConfiguredV8::'+dgCurrentUserId(),'1');if(j.testedModel)localStorage.setItem('dvirGymAiTestModelV8::'+dgCurrentUserId(),j.testedModel);toast('✦ Zero‑Cost AI מחובר לחשבון האישי');setTimeout(()=>{renderMore();checkAIHealth();switchScreen('coach')},160);return true}catch(e){toast(typeof dgAIErrorMessage==='function'?dgAIErrorMessage(e):'חיבור ה־AI נכשל; Memory Engine ממשיך לעבוד');return false}};
dgActivateAI=async function(){if(!dgIsAccount()){dgOpenAccount('login');return}const input=$('#dgFreeAiKey'),btn=$('#dgActivateAI');if(!input||!btn)return;const key=input.value.trim();if(key.length<30){toast('הדבק OpenRouter API key תקין');return}btn.disabled=true;try{const j=await dgKeyVault('set',key);input.value='';dgAiConfigured=true;localStorage.setItem('dvirGymAiConfiguredV8::'+dgCurrentUserId(),'1');toast(`✦ AI חינמי הופעל לחשבון${j.testedModel?' · '+j.testedModel:''}`);renderMore();setTimeout(()=>switchScreen('coach'),150)}catch(e){toast(dgAIErrorMessage?.(e)||'לא הצלחתי להפעיל AI');btn.disabled=false}};
dgDeleteAI=async function(){if(!dgIsAccount())return;if(!confirm('לנתק את OpenRouter החינמי מהחשבון הזה?'))return;try{await dgKeyVault('delete');dgAiConfigured=false;localStorage.setItem('dvirGymAiConfiguredV8::'+dgCurrentUserId(),'0');toast('מפתח ה־AI הוסר מהחשבון');renderMore()}catch{toast('לא הצלחתי לנתק כרגע')}};

// User-scoped Web Push. Guest mode keeps local/Calendar reminders only.
dgPushRequest=async function(payload){if(!dgIsAccount())throw new Error('account_required');const c=new AbortController(),t=setTimeout(()=>c.abort(),20000);try{const headers=await dgAuthHeaders(),r=await fetch(DG_USER_PUSH_URL,{method:'POST',headers,body:JSON.stringify(payload),signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw new Error(j.error||('push '+r.status));return j}finally{clearTimeout(t)}};
const requestNotificationsV8Base=requestNotifications;requestNotifications=async function(){if(!dgIsAccount()){toast('Push אישי דורש חשבון כדי לא לערבב תזכורות בין אנשים');dgOpenAccount('login');return}return requestNotificationsV8Base()};

// User-scoped privacy control.
dgPrivacy=async function(action='status'){if(!dgIsAccount()){if(action==='status')return{ok:true,guest:true,memory:false,pushDevices:0,quota:false,ai:false};return{ok:true,guest:true,wiped:[]}}const c=new AbortController(),t=setTimeout(()=>c.abort(),20000);try{const headers=await dgAuthHeaders(),r=await fetch(DG_USER_PRIVACY_URL,{method:'POST',headers,body:JSON.stringify({action}),signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok)throw new Error(j.error||('privacy '+r.status));return j}finally{clearTimeout(t)}};

function dgAuthError(e){const s=String(e?.message||e||'');if(s.includes('username_taken'))return'שם המשתמש כבר תפוס. בחר שם אחר.';if(s.includes('invalid_credentials'))return'שם המשתמש או הסיסמה אינם נכונים.';if(s.includes('weak_password'))return'הסיסמה צריכה להכיל לפחות 8 תווים.';if(s.includes('invalid_username'))return'שם משתמש: 3–30 תווים, אותיות/מספרים/נקודה/מקף/קו תחתון.';if(s.includes('invalid_recovery'))return'שם המשתמש או Recovery Key אינם תואמים.';if(s.includes('rate_limited'))return'בוצעו יותר מדי ניסיונות. המתן מעט ונסה שוב.';return'לא הצלחתי להשלים את הפעולה כרגע. נסה שוב.'}
function dgEnsureAccountDialog(){let d=$('#dgAccountDialog');if(d)return d;d=document.createElement('dialog');d.id='dgAccountDialog';d.className='dg-auth-dialog';d.innerHTML='<div id="dgAccountDialogBody"></div>';document.body.appendChild(d);d.addEventListener('cancel',e=>{e.preventDefault();d.close()});return d}
function dgAccountHeader(sub='המידע של כל משתמש נשאר נפרד'){return`<div class="dg-auth-head"><div class="logo">AI</div><div><h2>Dvir Gym AI</h2><small>${esc(sub)}</small></div><button class="dg-auth-close" id="dgAuthClose">×</button></div>`}
function dgFormError(){return'<div class="dg-auth-error" id="dgAuthError"></div>'}
function dgShowAuthError(text){const e=$('#dgAuthError');if(e){e.textContent=text;e.classList.add('show')}}
function dgRenderAccount(mode=dgAccountMode){dgAccountMode=mode;const d=dgEnsureAccountDialog(),b=$('#dgAccountDialogBody'),account=dgIsAccount(),recovery=dgAccountRecovery();if(account&&mode==='home'){
 const name=dgCurrentDisplayName(),username=dgCurrentUsername(),initial=(name||username||'U').trim().charAt(0).toUpperCase(),guest=dgGuestState();b.innerHTML=`<div class="dg-auth-shell">${dgAccountHeader('חשבון אישי · נתונים מבודדים מכל משתמש אחר')}<div class="dg-user-hero"><div class="dg-user-avatar">${esc(initial)}</div><div><h3>${esc(name)}</h3><p>@${esc(username)} · ${recovery?'Cloud Memory פתוח':'Cloud Memory נעול במכשיר הזה'}</p></div><span class="badge dg-free-badge">ACCOUNT</span></div><div class="dg-account-state"><div><small>LOCAL DATA</small><b>PRIVATE</b></div><div><small>CLOUD</small><b>${recovery?'READY':'LOCKED'}</b></div><div><small>AI</small><b>${dgAiConfigured?'FREE LIVE':'OPTIONAL'}</b></div></div>${!recovery?'<button class="primary" id="dgUnlockCloud">הזן Recovery Key ופתח Cloud Memory</button>':'<button class="secondary" id="dgCopyAccountRecovery">העתק Recovery Key מהמכשיר הזה</button>'}${dgMeaningfulState(guest)?'<div class="dg-migration"><b>יש גם נתונים ממצב האורח במכשיר</b><p>אפשר למזג אותם פעם אחת לתוך החשבון הנוכחי בלי למחוק את מה שכבר קיים.</p><button class="secondary" id="dgImportGuest">מזג נתוני אורח לחשבון</button></div>':''}<div class="dg-account-actions"><button class="secondary" id="dgAccountProfile">ערוך Athlete Profile</button><button class="ghost" id="dgAccountLogout">התנתק</button></div><p class="dg-auth-note">אותו לינק יכול לשמש כמה אנשים. כל חשבון מקבל UUID, זיכרון מקומי, Cloud Memory, AI ו־Push משלו. המשתמש הבא לא רואה את הנתונים שלך.</p></div>`;
 }else if(account&&mode==='unlock')b.innerHTML=`<div class="dg-auth-shell">${dgAccountHeader('פתיחת הזיכרון המוצפן במכשיר הזה')}<div class="dg-auth-note">החשבון מחובר, אבל כדי לפענח את Cloud Memory במכשיר חדש צריך את ה־Recovery Key שקיבלת בעת ההרשמה. הוא אינו נשמר בשרת כטקסט קריא.</div><div class="dg-auth-form" style="margin-top:12px"><div class="field"><label>Recovery Key</label><input id="dgUnlockRecovery" autocomplete="off" spellcheck="false" placeholder="הדבק את המפתח הפרטי"></div>${dgFormError()}<button class="primary" id="dgUnlockRecoveryBtn">פתח וסנכרן Cloud Memory</button></div></div>`;
 else if(mode==='recovery-save')b.innerHTML=`<div class="dg-auth-shell">${dgAccountHeader('שלב אחד חשוב לפני שממשיכים')}<div class="dg-recovery-box"><b>שמור את Recovery Key</b><p class="help">זה המפתח לשחזור הסיסמה ולפענוח הזיכרון שלך בטלפון חדש. אנחנו שומרים בשרת רק hash — לא ניתן להציג לך את המפתח שוב אם תאבד אותו.</p><div class="dg-recovery-key" id="dgRecoveryText">${esc(dgRecoveryReveal)}</div><button class="secondary" id="dgCopyRecoveryNew">העתק Recovery Key</button></div><button class="primary" id="dgRecoverySaved">שמרתי את המפתח · המשך</button></div>`;
 else if(mode==='recover')b.innerHTML=`<div class="dg-auth-shell">${dgAccountHeader('שחזור סיסמה ללא אימייל או SMS')}<div class="dg-auth-form"><div class="field"><label>שם משתמש</label><input id="dgRecoverUser" autocomplete="username"></div><div class="field"><label>Recovery Key</label><input id="dgRecoverKey" autocomplete="off" spellcheck="false"></div><div class="field"><label>סיסמה חדשה</label><input id="dgRecoverPassword" type="password" autocomplete="new-password"></div>${dgFormError()}<button class="primary" id="dgRecoverBtn">החלף סיסמה</button><button class="ghost" id="dgBackLogin">חזרה לכניסה</button></div></div>`;
 else if(mode==='signup'||mode==='login')b.innerHTML=`<div class="dg-auth-shell">${dgAccountHeader(mode==='signup'?'צור מרחב אישי משלך':'חזור למרחב האישי שלך')}<div class="dg-auth-tabs"><button data-auth-tab="login" class="${mode==='login'?'active':''}">כניסה</button><button data-auth-tab="signup" class="${mode==='signup'?'active':''}">חשבון חדש</button></div><div class="dg-auth-form">${mode==='signup'?'<div class="field"><label>איך לקרוא לך?</label><input id="dgSignupName" autocomplete="name" placeholder="למשל עדן כהן"></div>':''}<div class="field"><label>שם משתמש</label><input id="dgAuthUser" autocomplete="username" placeholder="שם ייחודי"></div><div class="field"><label>סיסמה</label><input id="dgAuthPassword" type="password" autocomplete="${mode==='signup'?'new-password':'current-password'}" placeholder="לפחות 8 תווים"></div>${dgFormError()}<button class="primary" id="dgAuthSubmit">${mode==='signup'?'צור חשבון אישי':'היכנס לחשבון'}</button>${mode==='login'?'<button class="ghost" id="dgForgot">שכחתי סיסמה · יש לי Recovery Key</button>':''}</div><p class="dg-auth-note">אין צורך באימייל או מספר טלפון. החשבון משתמש ב־Supabase Auth מאחורי הקלעים, והמידע האישי שלך מופרד לפי User ID.</p></div>`;
 else b.innerHTML=`<div class="dg-auth-shell">${dgAccountHeader('אותו לינק · מרחב נפרד לכל אדם')}<div class="dg-auth-choice"><button class="primary" id="dgChooseSignup"><b>צור חשבון אישי</b><small>סנכרון בין מכשירים · AI אישי · Push אישי · Cloud Memory מוצפן</small></button><button class="secondary" id="dgChooseLogin"><b>יש לי כבר חשבון</b><small>היכנס בשם משתמש וסיסמה</small></button><button class="ghost" id="dgChooseGuest"><b>המשך כאורח</b><small>הכול נשמר רק בדפדפן הזה · ללא Cloud</small></button></div><p class="dg-auth-note" style="margin-top:12px">דביר, עדן וכל משתמש נוסף יכולים לפתוח את אותו URL. החשבונות אינם חולקים אימונים, אוכל, משקל, היקפים, צ׳אט, AI או תזכורות.</p></div>`;
 $('#dgAuthClose')?.addEventListener('click',()=>d.close());$$('[data-auth-tab]',b).forEach(x=>x.onclick=()=>dgRenderAccount(x.dataset.authTab));$('#dgChooseSignup')?.addEventListener('click',()=>dgRenderAccount('signup'));$('#dgChooseLogin')?.addEventListener('click',()=>dgRenderAccount('login'));$('#dgChooseGuest')?.addEventListener('click',()=>{localStorage.setItem(DG_WELCOME_KEY,'1');d.close();dgShowScopeBanner()});$('#dgForgot')?.addEventListener('click',()=>dgRenderAccount('recover'));$('#dgBackLogin')?.addEventListener('click',()=>dgRenderAccount('login'));$('#dgAccountLogout')?.addEventListener('click',dgLogout);$('#dgAccountProfile')?.addEventListener('click',()=>{d.close();openProfile()});$('#dgUnlockCloud')?.addEventListener('click',()=>dgRenderAccount('unlock'));$('#dgCopyAccountRecovery')?.addEventListener('click',dgCopyRecovery);$('#dgImportGuest')?.addEventListener('click',dgImportGuestIntoAccount);$('#dgRecoverySaved')?.addEventListener('click',()=>{dgRecoveryReveal='';dgRenderAccount('home');setTimeout(()=>dgCloudBoot(),150)});$('#dgCopyRecoveryNew')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(dgRecoveryReveal);toast('Recovery Key הועתק')}catch{}});$('#dgAuthSubmit')?.addEventListener('click',()=>dgSubmitAuth(mode));$('#dgRecoverBtn')?.addEventListener('click',dgRecoverAccount);$('#dgUnlockRecoveryBtn')?.addEventListener('click',dgUnlockCloud);
}
