async function dgSubmitAuth(mode){if(dgAuthBusy)return;const username=$('#dgAuthUser')?.value.trim(),password=$('#dgAuthPassword')?.value||'',displayName=$('#dgSignupName')?.value.trim()||username;dgAuthBusy=true;const btn=$('#dgAuthSubmit');if(btn){btn.disabled=true;btn.textContent='מתחבר…'}try{dgWriteScopedState(S);const guest=dgGuestState()||S,j=await dgAccountRequest({action:mode,username,password,displayName});dgStoreSession(j.session,{username:j.username||username,displayName:j.displayName||displayName});if(j.recoveryKey){localStorage.setItem(dgRecoveryStorageKey(j.session.user.id),j.recoveryKey);dgRecoveryReveal=j.recoveryKey}const existing=dgReadScopedState('user:'+j.session.user.id);S=existing||dgFreshUserState(j.displayName||j.session.user.user_metadata?.full_name||username);dgWriteScopedState(S);dgSetActiveScope();dgPendingGuestImport=!existing&&dgMeaningfulState(guest);await dgAuthEnsure();toast(mode==='signup'?'החשבון האישי נוצר':'ברוך הבא חזרה');try{renderCurrent()}catch{}if(j.recoveryKey)dgRenderAccount('recovery-save');else{dgRenderAccount('home');if(dgAccountRecovery())setTimeout(()=>dgCloudBoot(),150)}dgShowScopeBanner()}catch(e){dgShowAuthError(dgAuthError(e));if(btn){btn.disabled=false;btn.textContent=mode==='signup'?'צור חשבון אישי':'היכנס לחשבון'}}finally{dgAuthBusy=false}}
