window.addEventListener('pagehide',()=>{if(dgIdentityTransition)return;try{dgWriteScopedState(S,dgScope())}catch{}},{capture:true});
/* Athlete OS 8.0 — Scoped photos + neutral profile validation */
const dgPhotoScope=()=>dgScope();
saveProgressPhoto=async function(file){try{const data=await compressImage(file,900,.76),db=await openDB(),tx=db.transaction('photos','readwrite'),scope=dgPhotoScope();tx.objectStore('photos').put({id:`p_${scope.replace(/[^a-zA-Z0-9_-]/g,'_')}_${Date.now()}_${Math.random().toString(36).slice(2,7)}`,scope,ts:Date.now(),data});await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});toast('תמונת ההתקדמות נשמרה במרחב האישי הנוכחי');renderProgress()}catch{toast('לא הצלחתי לשמור את התמונה')}};
loadProgressPhotos=async function(){const g=$('#progressPhotoGrid');if(!g)return;try{const db=await openDB(),tx=db.transaction('photos','readonly'),r=tx.objectStore('photos').getAll(),all=await new Promise((res,rej)=>{r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)}),scope=dgPhotoScope(),arr=all.filter(x=>x.scope===scope||(!x.scope&&scope==='guest'));arr.sort((a,b)=>b.ts-a.ts);g.innerHTML=arr.length?arr.slice(0,12).map(x=>`<div class="progress-photo"><img src="${x.data}" alt="תמונת התקדמות"><small>${fmtDate(x.ts,{day:'2-digit',month:'2-digit'})}</small></div>`).join(''):'<div class="empty" style="grid-column:1/-1">עוד אין תמונות התקדמות במרחב הזה</div>';if(scope==='guest'){const legacy=arr.filter(x=>!x.scope);if(legacy.length){const w=db.transaction('photos','readwrite'),store=w.objectStore('photos');legacy.forEach(x=>store.put({...x,scope:'guest'}))}}}catch{g.innerHTML='<div class="empty" style="grid-column:1/-1">אחסון התמונות אינו זמין</div>'}};

function dgReadPositive(id,min,max,label,required=true){const el=$(id),raw=String(el?.value??'').trim();if(!raw){if(required)throw new Error(`חסר ${label}`);return''}const v=+raw;if(!Number.isFinite(v)||v<min||v>max)throw new Error(`${label} אינו בטווח תקין`);return v}
const dgOpenProfileNeutralBase=openProfile;
openProfile=function(){dgOpenProfileNeutralBase();const p=S.profile,name=$('#pName');if(name&&!name.value&&dgIsAccount())name.value=dgCurrentDisplayName();const saveBtn=$('#saveProfile');if(!saveBtn)return;saveBtn.onclick=()=>{try{const nm=$('#pName').value.trim()||(dgIsAccount()?dgCurrentDisplayName():'');if(!nm)throw new Error('חסר שם');const age=dgReadPositive('#pAge',18,100,'גיל'),height=dgReadPositive('#pHeight',120,230,'גובה'),weight=dgReadPositive('#pWeight',35,300,'משקל'),target=dgReadPositive('#pTarget',35,300,'משקל יעד'),days=dgReadPositive('#pDays',2,6,'מספר אימונים');p.name=nm;p.age=age;p.height=height;p.weight=weight;p.targetWeight=target;p.days=Math.round(days);p.experience=$('#pExperience').value;p.priority=parsePriority($('#pPriority').value);p.injuries=$('#pInjuries').value.trim();p.activity=$('#pActivity').value;p.dietStyle=$('#pDiet').value.trim();p.wake=$('#pWake').value;p.sleep=$('#pSleep').value;p.likes=$('#pLikes').value.trim();p.dislikes=$('#pDislikes').value.trim();p.allergies=$('#pAllergies').value.trim();p.equipment=$('#pEquipment').value.trim();p.creatine=$('#pCreatine').checked;p.manualCalories=$('#pManualCal').value;p.manualProtein=$('#pManualPro').value;p.complete=true;save();$('#profileDialog').close();dgUpdateIdentityChrome();renderCurrent();toast('Athlete Profile נשמר למשתמש הנוכחי')}catch(e){toast(String(e.message||e))}}};

const dgRenderOnboardingValidatedBase=renderOnboarding;
renderOnboarding=function(){dgRenderOnboardingValidatedBase();const next=$('#obNext');if(!next)return;const original=next.onclick;next.onclick=()=>{if(onboardingStep===1){try{dgReadPositive('#obAge',18,100,'גיל');dgReadPositive('#obHeight',120,230,'גובה');dgReadPositive('#obWeight',35,300,'משקל');dgReadPositive('#obTarget',35,300,'משקל יעד')}catch(e){toast(String(e.message||e));return}}return original?.()}};

// New accounts never inherit a hardcoded person's identity or metrics.
const dgFreshUserStateSafeBase=dgFreshUserState;dgFreshUserState=function(name=''){const x=dgFreshUserStateSafeBase(name);x.profile={...x.profile,name:name||'',age:'',height:'',weight:'',targetWeight:'',complete:false};return x};
/* Athlete OS 8.0 — Account ownership, password UX, scoped foreground reminders */
const DG_USER_ACCOUNT_URL=DG_SUPABASE_URL+'/functions/v1/user-account';

dgAuthError=function(e){const s=String(e?.message||e||'');if(s.includes('username_taken'))return'שם המשתמש כבר תפוס. בחר שם אחר.';if(s.includes('invalid_credentials'))return'שם המשתמש או הסיסמה אינם נכונים.';if(s.includes('weak_password'))return'הסיסמה צריכה להכיל לפחות 10 תווים, כולל אות ומספר.';if(s.includes('invalid_username'))return'שם משתמש: 3–30 תווים, אותיות/מספרים/נקודה/מקף/קו תחתון.';if(s.includes('invalid_recovery'))return'שם המשתמש או Recovery Key אינם תואמים.';if(s.includes('rate_limited'))return'בוצעו יותר מדי ניסיונות. המתן מעט ונסה שוב.';return'לא הצלחתי להשלים את הפעולה כרגע. נסה שוב.'};

async function dgUserAccountRequest(body){if(!dgIsAccount())throw new Error('account_required');const c=new AbortController(),t=setTimeout(()=>c.abort(),25000);try{const headers=await dgAuthHeaders(),r=await fetch(DG_USER_ACCOUNT_URL,{method:'POST',headers,body:JSON.stringify(body),signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok){const e=new Error(j.error||('account '+r.status));e.data=j;e.status=r.status;throw e}return j}finally{clearTimeout(t)}}
async function dgDeleteLocalPhotosForScope(scope){try{const db=await openDB(),tx=db.transaction('photos','readwrite'),store=tx.objectStore('photos'),req=store.openCursor();await new Promise((resolve,reject)=>{req.onsuccess=()=>{const cur=req.result;if(!cur)return resolve();if(cur.value?.scope===scope)cur.delete();cur.continue()};req.onerror=()=>reject(req.error)});await new Promise(r=>{tx.oncomplete=r;tx.onerror=r})}catch{}}
async function dgDeleteAccountNow(){if(dgAuthBusy)return;const username=$('#dgDeleteUsername')?.value.trim().toLocaleLowerCase('he-IL'),password=$('#dgDeletePassword')?.value||'',expected=dgCurrentUsername().toLocaleLowerCase('he-IL');if(username!==expected){dgShowAuthError(`כדי לאשר, הקלד בדיוק: ${expected}`);return}if(!password){dgShowAuthError('הזן את הסיסמה הנוכחית.');return}const btn=$('#dgDeleteAccountConfirm');dgAuthBusy=true;if(btn){btn.disabled=true;btn.textContent='מוחק את החשבון…'}const uid=dgCurrentUserId(),scope='user:'+uid;try{await dgUserAccountRequest({action:'delete-account',confirmUsername:username,password});dgIdentityTransition=true;try{await dgDeleteLocalPhotosForScope(scope)}catch{}localStorage.removeItem(dgScopedStateKey(scope));localStorage.removeItem(dgRecoveryStorageKey(uid));localStorage.removeItem(DG_CLOUD_META_PREFIX+scope);localStorage.removeItem(DG_CLOUD_DISABLED_PREFIX+scope);localStorage.removeItem(DG_THEME_SCOPE_PREFIX+scope);localStorage.removeItem('dvirGymAiConfiguredV8::'+uid);localStorage.removeItem(DG_AUTH_SESSION_KEY);localStorage.setItem(DG_ACTIVE_SCOPE_KEY,'guest');S=dgReadScopedState('guest')||dgFreshUserState('');dgWriteScopedState(S,'guest');dgIdentityTransition=false;toast('החשבון וכל נתוני הענן שלו נמחקו');$('#dgAccountDialog')?.close();setTimeout(()=>location.reload(),450)}catch(e){dgShowAuthError(String(e?.message||'').includes('invalid_credentials')?'הסיסמה אינה נכונה.':'לא הצלחתי למחוק את החשבון כרגע.');if(btn){btn.disabled=false;btn.textContent='מחק את החשבון לצמיתות'}}finally{dgAuthBusy=false}}

const dgRenderAccountOwnershipBase=dgRenderAccount;
dgRenderAccount=function(mode=dgAccountMode){if(mode==='delete'&&dgIsAccount()){dgAccountMode=mode;const d=dgEnsureAccountDialog(),b=$('#dgAccountDialogBody'),username=dgCurrentUsername();b.innerHTML=`<div class="dg-auth-shell">${dgAccountHeader('מחיקה בלתי הפיכה של החשבון האישי')}<div class="dg-auth-note" style="border-color:rgba(255,107,126,.24);background:rgba(255,107,126,.07)">הפעולה מוחקת את חשבון Supabase Auth, Cloud Memory, מפתח AI, מכסת AI ו־Push. גם הנתונים והתמונות המקומיים של החשבון הזה יימחקו מהמכשיר הנוכחי. נתוני Guest וחשבונות אחרים לא ייפגעו.</div><div class="dg-auth-form" style="margin-top:12px"><div class="field"><label>הקלד את שם המשתמש לאישור</label><input id="dgDeleteUsername" autocomplete="off" placeholder="${esc(username)}"></div><div class="field"><label>הסיסמה הנוכחית</label><input id="dgDeletePassword" type="password" autocomplete="current-password"></div>${dgFormError()}<button class="primary" id="dgDeleteAccountConfirm" style="background:linear-gradient(105deg,#ff6b7e,#ff8c68);color:#fff">מחק את החשבון לצמיתות</button><button class="ghost" id="dgDeleteCancel">ביטול</button></div></div>`;$('#dgAuthClose').onclick=()=>d.close();$('#dgDeleteCancel').onclick=()=>dgRenderAccount('home');$('#dgDeleteAccountConfirm').onclick=dgDeleteAccountNow;if(!d.open)d.showModal();return}dgRenderAccountOwnershipBase(mode);if(dgIsAccount()&&mode==='home'){const shell=$('#dgAccountDialogBody .dg-auth-shell');if(shell&&!$('#dgDeleteAccountOpen')){const btn=document.createElement('button');btn.id='dgDeleteAccountOpen';btn.className='ghost';btn.style.cssText='margin-top:10px;color:var(--danger,#ff6b7e);border-color:rgba(255,107,126,.2)';btn.textContent='מחק חשבון ונתונים';btn.onclick=()=>dgRenderAccount('delete');shell.appendChild(btn)}}if(mode==='signup'||mode==='recover'){const pw=mode==='signup'?$('#dgAuthPassword'):$('#dgRecoverPassword');if(pw)pw.placeholder='10+ תווים · לפחות אות ומספר';const note=$('#dgAccountDialogBody .dg-auth-note');if(note&&mode==='signup')note.innerHTML+=' <b>סיסמה:</b> לפחות 10 תווים, אות ומספר.'}}

checkForegroundReminders=function(){if(!('Notification' in window)||Notification.permission!=='granted')return;const n=new Date(),tm=n.toTimeString().slice(0,5),d=n.getDay(),base=`${dgScope()}-${nowDay()}-${tm}-`;for(const r of S.reminders)if(r.on&&r.time===tm&&r.days.includes(d)&&sessionStorage.getItem(base+r.id)!=='1'){navigator.serviceWorker?.ready.then(reg=>reg.showNotification('Dvir Gym AI',{body:r.name,icon:'assets/icon-192.png',badge:'assets/icon-192.png',tag:'dvir-'+dgScope()+'-'+r.id,data:{url:'./'}})).catch(()=>new Notification('Dvir Gym AI',{body:r.name}));sessionStorage.setItem(base+r.id,'1')}};
/* Athlete OS 8 — Theme Studio, smart signup, seamless multi-device cloud and private photos */
const DG_USER_PHOTOS_URL=DG_SUPABASE_URL+'/functions/v1/user-photos';
const DG_CLAIM_SESSION_KEY='dvirGymClaimV8';
const DG_PALETTES={
 bright:{label:'Crystal Light',desc:'לבן, תכלת וסגול נקי',meta:'#eef8ff'},
 cream:{label:'Ivory Cream',desc:'שמנת, זהב ולבן חם',meta:'#fbf3e6'},
 pearl:{label:'Gold · White · Rose',desc:'זהב, לבן וורוד פנינה',meta:'#fff8fa'},
 aurora:{label:'Aurora Fusion',desc:'תכלת, סגול, ורוד, מנטה וזהב',meta:'#f4fbff'},
 night:{label:'Night Neon',desc:'כהה, עמוק וזוהר',meta:'#05070b'},
 auto:{label:'Auto',desc:'לפי מצב הטלפון',meta:'#eef8ff'}
};

function dgCaptureClaimFromUrl(){try{const u=new URL(location.href),t=u.searchParams.get('claim');if(t&&t.length>20){sessionStorage.setItem(DG_CLAIM_SESSION_KEY,t);u.searchParams.delete('claim');history.replaceState(null,'',u.pathname+u.search+u.hash)}}catch{}}
function dgClaimToken(){return sessionStorage.getItem(DG_CLAIM_SESSION_KEY)||''}
dgCaptureClaimFromUrl();
let dgClaimInfo=null,dgUsernameDebounce=null,dgUsernameManual=false;

async function dgLoadClaimInfo(){const t=dgClaimToken();if(!t)return null;try{const j=await dgAccountRequest({action:'claim_info',claimToken:t});dgClaimInfo=j;return j}catch{sessionStorage.removeItem(DG_CLAIM_SESSION_KEY);dgClaimInfo=null;return null}}

function dgUsernameFromName(name=''){
 const compact=String(name).trim().replace(/[\s'"׳״-]+/g,'');
 if(compact==='דבירביטון')return'dvirbiton';
 if(compact==='עדןכהן')return'edencohen';
 const map={א:'a',ב:'b',ג:'g',ד:'d',ה:'h',ו:'v',ז:'z',ח:'h',ט:'t',י:'y',כ:'k',ך:'k',ל:'l',מ:'m',ם:'m',נ:'n',ן:'n',ס:'s',ע:'a',פ:'p',ף:'f',צ:'tz',ץ:'tz',ק:'k',ר:'r',ש:'sh',ת:'t'};
 let out='';
 for(const ch of String(name).toLowerCase()){if(/[a-z0-9]/.test(ch))out+=ch;else if(map[ch])out+=map[ch]}
 out=out.replace(/[^a-z0-9]/g,'').slice(0,24);
 return out.length>=3?out:'athlete'+String(Math.floor(10+Math.random()*90));
}
function dgUsernameIdeas(name=''){const base=dgUsernameFromName(name),yy=new Date().getFullYear()%100;return[base,`${base}${yy}`,`${base}.${String(Math.floor(10+Math.random()*90))}`].filter((x,i,a)=>x.length<=30&&a.indexOf(x)===i)}
async function dgAvailability(username){const u=String(username||'').trim().toLowerCase();if(u.length<3)return null;try{return await dgAccountRequest({action:'availability',username:u,claimToken:dgClaimToken()})}catch{return null}}
function dgPasswordScore(p='',u=''){let n=0;if(p.length>=10)n++;if(p.length>=14)n++;if(/[A-Za-zא-ת]/.test(p)&&/\d/.test(p))n++;if(/[^A-Za-zא-ת0-9]/.test(p))n++;if(u&&u.length>=4&&p.toLowerCase().includes(u.toLowerCase()))n=Math.max(0,n-2);return Math.max(0,Math.min(4,n))}
function dgPasswordStatus(p='',u=''){const score=dgPasswordScore(p,u);if(p.length<10)return{score,text:'לפחות 10 תווים'};if(!/[A-Za-zא-ת]/.test(p)||!/\d/.test(p))return{score:Math.min(score,1),text:'צריך לפחות אות ומספר'};if(u&&u.length>=4&&p.toLowerCase().includes(u.toLowerCase()))return{score:1,text:'אל תכלול את שם המשתמש בסיסמה'};return{score:Math.max(2,score),text:score>=4?'חזקה מאוד':score>=3?'חזקה':'תקינה · אפשר להוסיף סימן לחיזוק'}}

/* Theme Studio */
dgResolvedTheme=function(choice=dgThemeChoice()){if(choice==='auto')return matchMedia('(prefers-color-scheme: light)').matches?'bright':'night';return DG_PALETTES[choice]?choice:'bright'};
dgThemeChoice=function(){const fromState=dgIsAccount()?S?.prefs?.theme:'';return fromState||localStorage.getItem(DG_THEME_SCOPE_PREFIX+dgScope())||localStorage.getItem(DG_THEME_KEY)||'bright'};
dgApplyTheme=function(choice=dgThemeChoice(),persist=false){const resolved=dgResolvedTheme(choice),meta=DG_PALETTES[resolved]?.meta||'#eef8ff';if(persist){localStorage.setItem(DG_THEME_SCOPE_PREFIX+dgScope(),choice);if(!dgIsAccount())localStorage.setItem(DG_THEME_KEY,choice);if(S?.prefs){S.prefs.theme=choice;try{save()}catch{}}}document.documentElement.dataset.dgTheme=resolved;document.documentElement.dataset.dgThemeChoice=choice;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',meta);$$('.dg-theme-option').forEach(b=>b.classList.toggle('active',b.dataset.theme===choice));const live=$('#dgThemeLive');if(live){const p=DG_PALETTES[choice]||DG_PALETTES[resolved];live.querySelector('b').textContent=p.label;live.querySelector('small').textContent=p.desc}return resolved};

dgInjectThemeCard=function(){const s=$('#screen-more');if(!s)return;let card=$('#dgThemeCard');if(!card){card=document.createElement('div');card.id='dgThemeCard';card.className='card dg-theme-card';const anchor=$('#dgLaunchChecklist');if(anchor)anchor.insertAdjacentElement('afterend',card);else s.prepend(card)}const choice=dgThemeChoice();card.innerHTML=`<div class="section-head" style="margin-top:0"><div><h2>Theme Studio</h2><small>המערכת שלך · הצבעים שלך</small></div><span class="badge">LIVE</span></div><p class="dg-theme-studio-intro">בחר אווירה בלחיצה אחת. בחשבון אישי הבחירה נשמרת יחד עם שאר הנתונים וחוזרת איתך גם למכשיר אחר.</p><div class="dg-theme-options">${Object.entries(DG_PALETTES).map(([k,v])=>`<button class="dg-theme-option ${choice===k?'active':''}" data-theme="${k}"><i></i><b>${esc(v.label)}</b><small>${esc(v.desc)}</small></button>`).join('')}</div><div class="dg-theme-live" id="dgThemeLive"><div><b>${esc((DG_PALETTES[choice]||DG_PALETTES[dgResolvedTheme(choice)]).label)}</b><small>${esc((DG_PALETTES[choice]||DG_PALETTES[dgResolvedTheme(choice)]).desc)}</small></div><span class="badge">PREVIEW</span></div>`;$$('.dg-theme-option',card).forEach(b=>b.onclick=()=>{dgApplyTheme(b.dataset.theme,true);toast(`${DG_PALETTES[b.dataset.theme]?.label||'ערכת הצבעים'} הופעלה`)})};

function dgCreatorSignature(){return`<div class="dg-creator-signature"><b>נוצר ע״י דביר ביטון · מייסד קהילת Explain</b><p>בינה מלאכותית בסבלנות ובפשטות. <span class="dg-gift">האתר נוצר כמתנה מיוחדת עבור דוני (עדן) כהן.</span></p></div>`}
function dgInjectCreatorSignature(root){if(root&&!root.querySelector('.dg-creator-signature'))root.insertAdjacentHTML('beforeend',dgCreatorSignature())}
const dgRenderHomePremiumBase=renderHome;renderHome=function(){const r=dgRenderHomePremiumBase();setTimeout(()=>dgInjectCreatorSignature($('#screen-home')),30);return r};
const dgRenderMorePremiumBase=renderMore;renderMore=function(){const r=dgRenderMorePremiumBase();setTimeout(()=>{dgInjectThemeCard();dgInjectCreatorSignature($('#screen-more'));dgApplyTheme(dgThemeChoice())},120);return r};

/* Account UX */
function dgEnhanceAuthUX(mode){const shell=$('#dgAccountDialogBody .dg-auth-shell');if(!shell)return;dgInjectCreatorSignature(shell);
 if(mode==='home'&&!dgIsAccount()){const choice=shell.querySelector('.dg-auth-choice');if(choice&&!shell.querySelector('.dg-auth-flow-title'))choice.insertAdjacentHTML('beforebegin','<div class="dg-auth-flow-title"><b>אותו לינק. חשבון אישי לכל אדם.</b><small>פותחים את הקישור, יוצרים חשבון או נכנסים לחשבון קיים — וכל האימונים, התזונה, התמונות, ה־AI וההעדפות שייכים רק לאותו משתמש.</small></div>');return}
 if((mode==='signup'||mode==='login')&&!shell.querySelector('.dg-auth-flow-title')){const form=shell.querySelector('.dg-auth-form');if(!form)return;form.insertAdjacentHTML('beforebegin',`<div class="dg-auth-flow-title"><b>${mode==='signup'?'60 שניות ויש לך Athlete OS משלך':'החשבון שלך מחכה לך'}</b><small>${mode==='signup'?'שם → Username → סיסמה. זה הכול.':'אותו Username ואותה סיסמה עובדים בטלפון, במחשב ובטאבלט.'}</small></div><div class="dg-auth-steps"><div class="dg-auth-step active">1 · זהות</div><div class="dg-auth-step active">2 · אבטחה</div><div class="dg-auth-step active">3 · Cloud</div></div>`);
  const u=$('#dgAuthUser'),pw=$('#dgAuthPassword'),name=$('#dgSignupName');
  if(u&&!$('#dgUsernameAssist'))u.parentElement?.insertAdjacentHTML('beforeend','<div class="dg-username-assist" id="dgUsernameAssist"><span class="dg-username-dot"></span><span>בחר שם קצר שקל לזכור</span></div><div class="dg-suggestion-row" id="dgUsernameIdeas"></div>');
  if(pw&&!pw.closest('.dg-password-wrap')){const par=pw.parentElement;if(par){const wrap=document.createElement('div');wrap.className='dg-password-wrap';par.insertBefore(wrap,pw);wrap.appendChild(pw);const toggle=document.createElement('button');toggle.type='button';toggle.className='dg-password-toggle';toggle.textContent='הצג';toggle.onclick=()=>{pw.type=pw.type==='password'?'text':'password';toggle.textContent=pw.type==='password'?'הצג':'הסתר'};wrap.appendChild(toggle);wrap.insertAdjacentHTML('afterend','<div class="dg-password-meter" id="dgPasswordMeter" data-score="0"><i></i><i></i><i></i><i></i></div><div class="dg-password-hint" id="dgPasswordHint">10+ תווים, אות ומספר. מומלץ גם סימן.</div>')}}
  const updatePw=()=>{if(!pw)return;const st=dgPasswordStatus(pw.value,u?.value||''),m=$('#dgPasswordMeter'),h=$('#dgPasswordHint');if(m)m.dataset.score=String(st.score);if(h)h.textContent=st.text};pw?.addEventListener('input',updatePw);u?.addEventListener('input',updatePw);
  const checkUser=async()=>{if(!u)return;const box=$('#dgUsernameAssist'),v=u.value.trim().toLowerCase();if(!box)return;if(v.length<3){box.className='dg-username-assist';box.lastElementChild.textContent='לפחות 3 תווים';return}box.className='dg-username-assist checking';box.lastElementChild.textContent='בודק זמינות…';const j=await dgAvailability(v);if(!j){box.className='dg-username-assist';box.lastElementChild.textContent='הזמינות תיבדק בזמן יצירת החשבון';return}box.className='dg-username-assist '+(j.available?'good':'bad');box.lastElementChild.textContent=j.available?'השם פנוי ✓':j.reserved?'השם שמור להזמנה אישית':'השם כבר תפוס'};
  const queue=()=>{clearTimeout(dgUsernameDebounce);dgUsernameDebounce=setTimeout(checkUser,350)};u?.addEventListener('input',()=>{dgUsernameManual=true;queue()});
  const ideas=()=>{if(!name||!u)return;const list=dgUsernameIdeas(name.value),row=$('#dgUsernameIdeas');if(row)row.innerHTML=list.map(x=>`<button type="button" data-user-idea="${x}">@${x}</button>`).join('');$$('[data-user-idea]',row).forEach(b=>b.onclick=()=>{u.value=b.dataset.userIdea;dgUsernameManual=true;queue()});if(!dgUsernameManual&&list[0]){u.value=list[0];queue()}};name?.addEventListener('input',ideas);
  if(mode==='signup'&&dgClaimInfo){if(name)name.value=dgClaimInfo.displayName||'';if(u){u.value=dgClaimInfo.username||'';u.readOnly=true}dgUsernameManual=true;shell.querySelector('.dg-auth-flow-title')?.insertAdjacentHTML('afterend',`<div class="dg-claim-badge"><span>✦</span><div><strong>הזמנה אישית עבור ${esc(dgClaimInfo.displayName||'')}</strong><small>שם המשתמש ${esc(dgClaimInfo.username||'')} שמור להזמנה הזאת.</small></div></div>`);queue()}else if(mode==='signup')ideas();
  form.insertAdjacentHTML('beforeend','<div class="dg-device-note"><span>⌁</span><div><b>נכנסים מכל מכשיר</b><small>אחרי יצירת החשבון, Username + Password מספיקים כדי לפתוח את Cloud Memory. Recovery Key נשאר מפתח חירום.</small></div></div>');
  [name,u,pw].filter(Boolean).forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#dgAuthSubmit')?.click()}}));
 }
 if(dgIsAccount()&&mode==='home'&&!shell.querySelector('.dg-device-note')){const state=shell.querySelector('.dg-account-state')||shell.querySelector('.dg-auth-note');state?.insertAdjacentHTML('afterend','<div class="dg-device-note"><span>☁</span><div><b>Multi‑Device Sync פעיל</b><small>אפשר להיכנס מכל מכשיר עם אותו Username וסיסמה. Cloud Memory, Theme ותמונות התקדמות נשארים משויכים ל־User ID שלך בלבד.</small></div></div>')}
}
const dgRenderAccountPremiumBase=dgRenderAccount;dgRenderAccount=function(mode=dgAccountMode){const r=dgRenderAccountPremiumBase(mode);setTimeout(()=>dgEnhanceAuthUX(mode),0);return r};

dgAuthError=function(e){const s=String(e?.message||e||'');if(s.includes('username_reserved'))return'שם המשתמש הזה שמור להזמנה אישית.';if(s.includes('username_taken'))return'שם המשתמש כבר תפוס. נסה אחת מההצעות.';if(s.includes('invalid_credentials'))return'שם המשתמש או הסיסמה אינם נכונים.';if(s.includes('weak_password'))return'הסיסמה צריכה להכיל לפחות 10 תווים, אות ומספר, ולא לכלול את שם המשתמש.';if(s.includes('invalid_username'))return'שם משתמש: 3–30 תווים, אותיות/מספרים/נקודה/מקף/קו תחתון.';if(s.includes('invalid_recovery'))return'שם המשתמש או Recovery Key אינם תואמים.';if(s.includes('rate_limited'))return'בוצעו יותר מדי ניסיונות. המתן מעט ונסה שוב.';return'לא הצלחתי להשלים את הפעולה כרגע. נסה שוב.'};

/* Username/password login silently restores the wrapped Recovery Key on a trusted successful login. */
dgSubmitAuth=async function(mode){if(dgAuthBusy)return;const username=$('#dgAuthUser')?.value.trim(),password=$('#dgAuthPassword')?.value||'',displayName=$('#dgSignupName')?.value.trim()||username;dgAuthBusy=true;const btn=$('#dgAuthSubmit');if(btn){btn.disabled=true;btn.textContent=mode==='signup'?'יוצר את המרחב שלך…':'פותח את החשבון…'}try{dgWriteScopedState(S);const guest=dgGuestState()||S,j=await dgAccountRequest({action:mode,username,password,displayName,claimToken:dgClaimToken()});dgStoreSession(j.session,{username:j.username||username,displayName:j.displayName||displayName});if(j.recoveryKey)localStorage.setItem(dgRecoveryStorageKey(j.session.user.id),j.recoveryKey);const existing=dgReadScopedState('user:'+j.session.user.id);S=existing||dgFreshUserState(j.displayName||j.session.user.user_metadata?.full_name||username);dgWriteScopedState(S);dgSetActiveScope();dgPendingGuestImport=!existing&&dgMeaningfulState(guest);await dgAuthEnsure();sessionStorage.removeItem(DG_CLAIM_SESSION_KEY);dgClaimInfo=null;renderCurrent();if(mode==='signup'&&j.recoveryKey){dgRecoveryReveal=j.recoveryKey;toast('החשבון נוצר · שמור את מפתח החירום');dgRenderAccount('recovery-save')}else{toast('ברוך הבא · מסנכרן את החשבון שלך');dgRenderAccount('home');setTimeout(()=>dgCloudBoot(),120);setTimeout(()=>dgSyncLocalPhotosToCloud(),900)}dgShowScopeBanner()}catch(e){dgShowAuthError(dgAuthError(e));if(btn){btn.disabled=false;btn.textContent=mode==='signup'?'צור חשבון אישי':'היכנס לחשבון'}}finally{dgAuthBusy=false}};

/* Private cloud photo layer */
async function dgUserPhotosRequest(body){if(!dgIsAccount())throw new Error('account_required');const headers=await dgAuthHeaders(),c=new AbortController(),timer=setTimeout(()=>c.abort(),35000);try{const r=await fetch(DG_USER_PHOTOS_URL,{method:'POST',headers,body:JSON.stringify(body),signal:c.signal}),j=await r.json().catch(()=>({}));if(!r.ok||!j.ok){const e=new Error(j.error||('photos '+r.status));e.data=j;e.status=r.status;throw e}return j}finally{clearTimeout(timer)}}
async function dgScopedLocalPhotos(){const db=await openDB(),tx=db.transaction('photos','readonly'),req=tx.objectStore('photos').getAll(),all=await new Promise((res,rej)=>{req.onsuccess=()=>res(req.result||[]);req.onerror=()=>rej(req.error)}),scope=dgPhotoScope();return all.filter(x=>x.scope===scope||(!x.scope&&scope==='guest')).sort((a,b)=>b.ts-a.ts)}
async function dgPutLocalPhoto(x){const db=await openDB(),tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(x);await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function dgDeleteLocalPhoto(id){const db=await openDB(),tx=db.transaction('photos','readwrite');tx.objectStore('photos').delete(id);await new Promise(r=>{tx.oncomplete=r;tx.onerror=r})}
async function dgUploadLocalPhotoRecord(x){if(!dgIsAccount()||!x?.data||x.cloudName)return x;const j=await dgUserPhotosRequest({action:'upload',data:x.data});x.cloudName=j.name;x.cloudSyncedAt=Date.now();await dgPutLocalPhoto(x);return x}
async function dgSyncLocalPhotosToCloud(){if(!dgIsAccount()||!navigator.onLine)return;try{const arr=await dgScopedLocalPhotos();for(const x of arr.filter(p=>p.data&&!p.cloudName).slice(0,10)){try{await dgUploadLocalPhotoRecord(x)}catch{break}}}catch{}}

saveProgressPhoto=async function(file){try{const data=await compressImage(file,900,.76),scope=dgPhotoScope(),x={id:`p_${scope.replace(/[^a-zA-Z0-9_-]/g,'_')}_${Date.now()}_${Math.random().toString(36).slice(2,7)}`,scope,ts:Date.now(),data};await dgPutLocalPhoto(x);if(dgIsAccount()&&navigator.onLine){try{await dgUploadLocalPhotoRecord(x);toast('התמונה נשמרה וסונכרנה לענן הפרטי')}catch{toast('התמונה נשמרה במכשיר · תסונכרן כשהחיבור יחזור')}}else toast(dgIsAccount()?'התמונה נשמרה · תסונכרן כשהחיבור יחזור':'התמונה נשמרה במצב אורח במכשיר הזה');renderProgress()}catch{toast('לא הצלחתי לשמור את התמונה')}};
function dgPhotoTile(x,source='local'){const src=x.url||x.data||'',date=x.createdAt?new Date(x.createdAt).getTime():x.ts||Date.now(),key=x.name||x.cloudName||x.id||'';return`<div class="progress-photo"><img src="${esc(src)}" alt="תמונת התקדמות"><small>${fmtDate(date,{day:'2-digit',month:'2-digit'})}</small>${dgIsAccount()?`<button class="dg-photo-delete" data-photo-key="${esc(key)}" data-photo-id="${esc(x.id||'')}" aria-label="מחק תמונה">×</button><span class="dg-photo-sync">${source==='cloud'?'☁ CLOUD':'LOCAL'}</span>`:''}</div>`}
async function dgDeletePhotoByButton(btn){const key=btn.dataset.photoKey||'',id=btn.dataset.photoId||'';if(!confirm('למחוק את תמונת ההתקדמות הזאת?'))return;btn.disabled=true;try{if(dgIsAccount()&&key.includes('.'))await dgUserPhotosRequest({action:'delete',name:key});const local=await dgScopedLocalPhotos();for(const x of local)if((id&&x.id===id)||(key&&(x.cloudName===key||x.id===key)))await dgDeleteLocalPhoto(x.id);toast('התמונה נמחקה');loadProgressPhotos()}catch{toast('לא הצלחתי למחוק את התמונה כרגע');btn.disabled=false}}
loadProgressPhotos=async function(){const g=$('#progressPhotoGrid');if(!g)return;g.innerHTML='<div class="empty" style="grid-column:1/-1">טוען את הגלריה האישית…</div>';try{const local=await dgScopedLocalPhotos();if(!dgIsAccount()){g.innerHTML=local.length?local.slice(0,12).map(x=>dgPhotoTile(x,'local')).join(''):'<div class="empty" style="grid-column:1/-1">עוד אין תמונות התקדמות</div>';return}let cloud=[];try{cloud=(await dgUserPhotosRequest({action:'list'})).items||[]}catch{}const cloudNames=new Set(cloud.map(x=>x.name)),pending=local.filter(x=>!x.cloudName||!cloudNames.has(x.cloudName));g.innerHTML=(cloud.length?cloud.slice(0,24).map(x=>dgPhotoTile(x,'cloud')).join(''):'')+(pending.length?pending.slice(0,8).map(x=>dgPhotoTile(x,x.cloudName?'cloud':'local')).join(''):'')+`<div class="dg-photo-cloud-note">${cloud.length?'☁ התמונות הפרטיות מסונכרנות לחשבון':'התמונות המקומיות יעלו לענן הפרטי כשהחיבור זמין'}</div>`;$$('.dg-photo-delete',g).forEach(b=>b.onclick=()=>dgDeletePhotoByButton(b));setTimeout(()=>dgSyncLocalPhotosToCloud(),250)}catch{g.innerHTML='<div class="empty" style="grid-column:1/-1">אחסון התמונות אינו זמין כרגע</div>'}};
window.addEventListener('online',()=>setTimeout(()=>dgSyncLocalPhotosToCloud(),600));

