function dgSessionIsPersistentV9(){return !!localStorage.getItem(DG_AUTH_SESSION_KEY)}
function dgRememberChoiceV9(){return localStorage.getItem(DG_REMEMBER_PREF)!=='0'}
function dgPersistSessionV9(next,remember=dgRememberChoiceV9()){localStorage.removeItem(DG_AUTH_SESSION_KEY);sessionStorage.removeItem(DG_AUTH_SESSION_KEY);(remember?localStorage:sessionStorage).setItem(DG_AUTH_SESSION_KEY,JSON.stringify(next));localStorage.setItem(DG_REMEMBER_PREF,remember?'1':'0')}
