dgAuthEnsure=async function(force=false){const s=dgAuthSession();if(!s)return null;const exp=(+s.expires_at||0)*1000;if(!force&&exp>Date.now()+90_000)return s;if(dgAuthRefreshPromise)return dgAuthRefreshPromise;dgAuthRefreshPromise=(async()=>{try{const r=await fetch(`${DG_SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:DG_SUPABASE_PUBLISHABLE,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})}),j=await r.json().catch(()=>({}));if(!r.ok||!j.access_token)throw new Error(j.error_description||j.message||'refresh_failed');const next={...j,expires_at:j.expires_at||Math.floor(Date.now()/1000)+(+j.expires_in||3600),accountUsername:s.accountUsername,displayName:s.displayName};dgPersistSessionV9(next,dgSessionIsPersistentV9());return next}catch(e){dgRecordError?.('auth-refresh',e);return s}finally{dgAuthRefreshPromise=null}})();return dgAuthRefreshPromise};
dgLogout=async function(){if(!dgIsAccount())return;dgWriteScopedState(S);await dgRemoveCurrentPushRegistration();try{const s=dgAuthSession();await fetch(`${DG_SUPABASE_URL}/auth/v1/logout`,{method:'POST',headers:{apikey:DG_SUPABASE_PUBLISHABLE,Authorization:`Bearer ${s.access_token}`}})}catch{}localStorage.removeItem(DG_AUTH_SESSION_KEY);sessionStorage.removeItem(DG_AUTH_SESSION_KEY);localStorage.setItem(DG_ACTIVE_SCOPE_KEY,'guest');const g=dgGuestState()||dgFreshUserState('');localStorage.setItem(STORE,JSON.stringify(g));toast('יצאת מהחשבון · חוזר למצב אורח');setTimeout(()=>location.reload(),350)};
