function dgRenderProfileAvatarEditorV9(){const root=$('#profileContent .sheet');if(!root)return;root.querySelector('.dg-profile-photo-card')?.remove();const head=root.querySelector('.sheet-head');const card=document.createElement('div');card.className='dg-profile-photo-card';card.innerHTML=`<div class="dg-profile-photo-preview">${dgAvatarUrlV9?`<img src="${esc(dgAvatarUrlV9)}" alt="תמונת פרופיל">`:`<span>${esc((S.profile?.name||dgCurrentDisplayName()||'א').slice(0,1))}</span>`}</div><div class="dg-profile-photo-copy"><b>תמונת הפרופיל שלך</b><small>${dgIsAccount()?'נשמרת בענן פרטי וחוזרת בכל מכשיר':'במצב אורח נשמרת רק במכשיר הזה'}</small><div><button id="dgChooseProfilePhoto">בחר תמונה</button>${dgAvatarUrlV9?'<button id="dgRemoveProfilePhoto">הסר</button>':''}</div></div>`;head?.insertAdjacentElement('afterend',card);$('#dgChooseProfilePhoto').onclick=()=>dgEnsureAvatarInputV9().click();$('#dgRemoveProfilePhoto')?.addEventListener('click',dgRemoveAvatarV9)}
