const dgInferMusclesV9Base=inferMuscles;inferMuscles=function(e){const id=e.exerciseId||e.mi||'',n=String(e.name||'').toLowerCase();if(id==='home-squeeze')return{chest:1,triceps:.45};if(id==='home-split')return{quads:1,glutes:.7};if(id==='home-calf'||/calf|תאומים/.test(n))return{calves:1};return dgInferMusclesV9Base(e)};
function dgDayOrdinalV9(ts){const d=new Date(ts);return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000)}
function dgNeedsRecoveryV9(){const ws=S.logs.filter(w=>(w.type||'')!=='recovery'&&(w.exercises||[]).some(e=>(e.results||[]).some(r=>r.done))).sort((a,b)=>(b.end||b.createdAt||0)-(a.end||a.createdAt||0));if(!ws.length)return false;const last=ws[0],lastTs=last.end||last.createdAt||0;if(Date.now()-lastTs<20*3600e3)return true;if(ws.length<2)return false;const a=dgDayOrdinalV9(lastTs),b=dgDayOrdinalV9(ws[1].end||ws[1].createdAt||0),today=dgDayOrdinalV9(Date.now());return a-b<=1&&today-a<=1}
const dgNextSplitV9Base=nextSplit;nextSplit=function(){const x=dgNextSplitV9Base();if(x==='recovery')return x;return dgNeedsRecoveryV9()?'recovery':x};
const dgLocalWorkoutV9Base=localWorkout;localWorkout=function(){const w=dgLocalWorkoutV9Base();if(w.type==='recovery')return w;if(readinessScore()>=72){const top=deficits().find(d=>d.score>1),pri=S.profile.priority||[];if(top&&(pri.includes(top.k)||top.pct<.45)){const ex=w.exercises.find(e=>Object.keys(inferMuscles(e)).includes(top.k));if(ex)ex.sets=Math.min(5,(+ex.sets||3)+1)}}w.reason=(w.reason||'')+' נפח העבודה מכוון לפי כיסוי 7 ימים, עדיפויות ויכולת התאוששות.';return w};
const dgProgressionV9Base=progressionAdvice;progressionAdvice=function(e){const last=findLastExercise(e);if(!last)return dgProgressionV9Base(e);const done=(last.results||[]).filter(x=>x.done),hi=repMax(e.reps),reps=done.map(x=>+x.reps||0),rir=done.map(x=>Number.isFinite(+x.rir)?+x.rir:2);if(!done.length||!hi||!reps.every(r=>r>=hi)||avg(rir)<1.5)return dgProgressionV9Base(e);if(e.exerciseId==='home-pushup')return{title:'התקדמות בשכיבות סמיכה',text:'הטווח העליון הושג. עבור לגרסה מעט קשה יותר — למשל רגליים מוגבהות על משטח יציב או עצירה של שנייה בתחתית — ושמור שוב 1–3 RIR.'};if(e.exerciseId==='home-pullup')return{title:'המתח מוכן להתקדמות',text:'אם כל החזרות נקיות, הוסף עומס קטן ובטוח אם יש דרך להצמידו, או האט את הירידה ל־3 שניות. אל תוסיף תנופה.'};if(e.exerciseId==='home-legraise')return{title:'בטן: העלה קושי, לא רק חזרות',text:'הוסף עצירה קצרה למעלה והטיית אגן, או האט את הירידה. שמור גב תחתון בשליטה.'};return dgProgressionV9Base(e)};
const dgBuildTodayV9Base=buildToday;buildToday=async function(){if(nextSplit()==='recovery'){S.activeWorkout=localWorkout();save();toast('היום Recovery — המערכת חוסמת עוד אימון כוח כבד כדי לשמור על התאוששות');openWorkout();return}return dgBuildTodayV9Base()};
const dgCoachMemoryV9Base=coachMemory;coachMemory=function(){return{...dgCoachMemoryV9Base(),experience:{special:!!dgExperienceV9.special,nickname:dgExperienceV9.nickname||'',tone:dgExperienceV9.tone||''},recoveryPolicy:{maxConsecutiveStrengthDays:2,forceRecoveryNow:dgNeedsRecoveryV9()}}};

function dgEnsureUpdateBannerV9(){let b=$('#dgUpdateBannerV9');if(b)return b;b=document.createElement('div');b.id='dgUpdateBannerV9';b.className='dg-update-banner';b.innerHTML='<div><span>↻</span><div><b>גרסה חדשה מוכנה</b><small>העדכון נשמר אוטומטית ולא מוחק את הנתונים שלך.</small></div></div><button id="dgApplyUpdateV9">עדכן עכשיו</button>';document.body.appendChild(b);$('#dgApplyUpdateV9').onclick=dgApplyReleaseV9;return b}
async function dgApplyReleaseV9(){try{if(S?.activeWorkout){toast('העדכון יחכה עד שתסיים את האימון');return}const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('dvir-athlete-os')).map(k=>caches.delete(k)));const reg=await navigator.serviceWorker?.getRegistration();await reg?.update();location.reload()}catch{location.reload()}}
async function dgCheckReleaseV9(){try{const r=await fetch(`version.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)return;const j=await r.json(),local=typeof DG_BUILD_ID!=='undefined'?DG_BUILD_ID:'';if(j?.build&&local&&j.build!==local){const b=dgEnsureUpdateBannerV9();b.classList.add('show');if(!S?.activeWorkout&&!document.querySelector('dialog[open]')){clearTimeout(dgReleaseTimerV9);dgReleaseTimerV9=setTimeout(dgApplyReleaseV9,9000)}}}catch{}}
async function dgV9Boot(){try{await dgLoadPersonalControlV9()}catch{}try{await dgLoadAvatarV9(true)}catch{}try{dgRefreshPersonalReminderV9()}catch{}try{await dgCheckReleaseV9()}catch{}setInterval(dgCheckReleaseV9,DG_RELEASE_POLL_MS);document.addEventListener('visibilitychange',()=>{if(!document.hidden){dgCheckReleaseV9();if(dgIsAccount())dgLoadAvatarV9()}})}
setTimeout(dgV9Boot,650);
/* Athlete OS 9.0.1 — atomic identity transitions: never let an account state save into Guest during logout. */
dgLogout=async function(){
 if(!dgIsAccount())return;
 const accountScope=dgScope();
 dgIdentityTransition=true;
 try{
  dgWriteScopedState(S,accountScope);
  try{await dgRemoveCurrentPushRegistration()}catch{}
  try{const s=dgAuthSession();if(s?.access_token)await fetch(`${DG_SUPABASE_URL}/auth/v1/logout`,{method:'POST',headers:{apikey:DG_SUPABASE_PUBLISHABLE,Authorization:`Bearer ${s.access_token}`}})}catch{}
  localStorage.removeItem(DG_AUTH_SESSION_KEY);
  sessionStorage.removeItem(DG_AUTH_SESSION_KEY);
  localStorage.setItem(DG_ACTIVE_SCOPE_KEY,'guest');
  const guest=dgGuestState()||dgFreshUserState('');
  S=dgNormalizeState(guest);
  dgWriteScopedState(S,'guest');
  try{if(typeof dgCloudPushTimer!=='undefined')clearTimeout(dgCloudPushTimer)}catch{}
  try{if(typeof dgPushSyncTimer!=='undefined')clearTimeout(dgPushSyncTimer)}catch{}
  dgAdminRoleV9='user';
  dgAdminShareV9={allow_admin:false,scopes:['workouts','nutrition','progress','profile']};
  dgAvatarUrlV9=S.profile?.avatarData||'';
 }finally{
  dgIdentityTransition=false;
 }
 try{renderCurrent();dgApplyAvatarV9();dgShowScopeBanner()}catch{}
 toast('יצאת מהחשבון · חוזר למצב אורח');
 setTimeout(()=>location.reload(),180);
};

/* Athlete OS 9 — AI Home Exercise Visuals: real technique cards, zero abstract-arrow fallback */
const DG_HOME_SPRITE_PARTS=['assets/home-sprite1.txt','assets/home-sprite2.txt'];
const DG_HOME_VISUAL_INDEX={
 'home-pushup':0,'home-pullup':1,'home-db-row':2,'home-floor-press':3,
 'home-shoulder':4,'home-lateral':5,'home-goblet':6,'home-rdl':7,
 'home-split':8,'home-calf':9,'home-curl':10,'home-triceps':11,'home-legraise':12
};
let dgHomeSpriteUrl='';
async function dgLoadHomeExerciseSprite(){
 if(dgHomeSpriteUrl)return dgHomeSpriteUrl;
 try{
  const parts=await Promise.all(DG_HOME_SPRITE_PARTS.map(async u=>{const r=await fetch(u,{cache:'force-cache'});if(!r.ok)throw new Error('home_sprite_'+r.status);return(await r.text()).trim()}));
  dgHomeSpriteUrl=`url("data:image/webp;base64,${parts.join('')}")`;
  dgApplyHomeWorkoutVisual();dgEnhanceHomeSwapVisuals();
  return dgHomeSpriteUrl;
 }catch(e){try{dgRecordError?.('home-exercise-sprite',e)}catch{}return''}
}
function dgHomeSpritePosition(id){const i=DG_HOME_VISUAL_INDEX[id];if(i==null)return null;const col=i%4,row=Math.floor(i/4);return`${(col/3*100).toFixed(4)}% ${(row/3*100).toFixed(4)}%`}
function dgPaintHomeSprite(el,id){const pos=dgHomeSpritePosition(id);if(!el||!pos||!dgHomeSpriteUrl)return false;el.style.backgroundImage=dgHomeSpriteUrl;el.style.backgroundSize='400% 400%';el.style.backgroundPosition=pos;el.style.backgroundRepeat='no-repeat';return true}
function dgApplyHomeWorkoutVisual(){
 const w=S.activeWorkout,e=w?.exercises?.[w.currentIndex||0],root=$('#workoutContent .home-visual');
 if(!root||!e||w?.location!=='home')return;
 const info=workoutInfo(e),has=DG_HOME_VISUAL_INDEX[e.exerciseId]!=null;
 root.classList.add('dg-home-visual-v9');
 root.innerHTML=`<div class="dg-home-technique-card" data-home-photo="${esc(e.exerciseId)}"></div><div class="dg-home-photo-meta"><span>AI TECHNIQUE CARD</span><b>${esc(info.pro||e.name)}</b><small>הדגמה חזותית · בצע לפי ה־cue וה־setup שמתחת לתמונה</small></div>`;
 const box=root.querySelector('[data-home-photo]');
 if(has&&dgPaintHomeSprite(box,e.exerciseId)){root.classList.add('loaded')}else{root.classList.remove('loaded');box.innerHTML='<div class="dg-home-photo-loading"><span>◌</span><b>טוען הדגמת תרגיל…</b></div>';dgLoadHomeExerciseSprite()}
}
const dgRenderWorkoutHomeVisualBase=renderWorkout;
renderWorkout=function(){const r=dgRenderWorkoutHomeVisualBase();setTimeout(dgApplyHomeWorkoutVisual,0);return r};

function dgEnhanceHomeSwapVisuals(){
 if(S.location!=='home')return;
 $$('.dg-swap-option[data-dg-swap]').forEach(b=>{if(b.querySelector('.dg-home-swap-thumb'))return;const id=b.dataset.dgSwap;if(DG_HOME_VISUAL_INDEX[id]==null)return;const thumb=document.createElement('i');thumb.className='dg-home-swap-thumb';b.prepend(thumb);dgPaintHomeSprite(thumb,id)})
}
const dgSwapExerciseHomeVisualBase=swapExercise;
swapExercise=function(e){const r=dgSwapExerciseHomeVisualBase(e);setTimeout(dgEnhanceHomeSwapVisuals,0);return r};

// Keep the home program aligned with the visuals and actual exercise technique.
if(homeMap['home-split']){
 homeMap['home-split'].simple='סקוואט בולגרי עם משקולות';
 homeMap['home-split'].pro='Bulgarian Split Squat';
 homeMap['home-split'].setup='הנח את הרגל האחורית על כיסא/משטח יציב. הרגל הקדמית רחוקה מספיק כדי לרדת בשליטה.';
 homeMap['home-split'].cue='רד כמעט אנכית דרך הרגל הקדמית; דחוף את כל כף הרגל לרצפה. אם אין משטח יציב — החלף ל־Goblet Squat.';
}
// Exercises without an exact photo are not offered by Smart Swap.
for(const id of ['home-lunge','home-squeeze']){const i=HOME_EX.findIndex(x=>x.id===id);if(i>=0)HOME_EX.splice(i,1);delete homeMap[id]}
